'use strict';
function catalogView(){const tabs=[['overview','Vista general','12'],['foundation','Fundamentos','05'],['controls','Controles','09'],['data','Datos & negocio','08'],['feedback','Feedback','06']];return `${title('DESIGN SYSTEM / VOL. 02','Cada detalle, en su elemento.','Un lenguaje visual. Infinitas posibilidades para tu negocio.',`<a class="btn secondary" href="ESPECIFICACION_GLASSY.md" download>${icon('download')}Especificación</a>${routeButton('Explorar el sistema','resumen','primary','arrow')}`)}<div class="glass-panel catalog-hero"><div><h2>Más claridad.<br><span>Un poco de glass.</span></h2><p>Componentes que se sienten tan bien como se ven.<br>Diseñados para conectar cada parte de tu negocio.</p><div class="flex">${badge('32+ componentes','orange')}${badge('2 temas · 6 acentos')}${badge('Flujos conectados')}</div></div><div class="hero-art" aria-hidden="true"><div class="glass-tile"></div><div class="glass-tile second"></div><div class="glass-tile third">a.</div><span class="art-label">MADE OF GLASS. BUILT FOR YOU.</span></div></div><div class="catalog-tabs" role="tablist" aria-label="Familias de componentes">${tabs.map(([id,label,n])=>`<button role="tab" id="tab-${id}" aria-controls="catalog-panel" tabindex="${ui.catalogTab===id?0:-1}" aria-selected="${ui.catalogTab===id}" class="${ui.catalogTab===id?'active':''}" data-catalog-tab="${id}">${label}<small>${n}</small></button>`).join('')}</div><div id="catalog-panel" role="tabpanel" aria-labelledby="tab-${ui.catalogTab}">${({overview:catalogOverview,foundation:catalogFoundation,controls:catalogControls,data:catalogData,feedback:catalogFeedback}[ui.catalogTab])()}</div>`}
function tokensPanel(){return `<div class="glass-panel">${panelHead('Colores con propósito','Un acento propio. Estados que se entienden.',`<span class="eyebrow" style="font-size:7px">01 / COLOR</span>`)}<div class="token-row">${[['Marca',state.prefs.accent,'--primary'],['Éxito',state.prefs.theme==='light'?'#168466':'#59d2af','--green'],['IA',state.prefs.theme==='light'?'#7852b9':'#b49aee','--purple'],['Alerta',state.prefs.theme==='light'?'#9d6b20':'#e9bd75','--amber'],['Error',state.prefs.theme==='light'?'#b8364e':'#f18b96','--red']].map(([n,c,t])=>`<button class="token" data-token="${t}" data-copy="${t==='--primary'?state.prefs.accent:c}" aria-label="Copiar color ${n}"><span class="color-block" style="--token:var(${t})"></span><strong>${n}</strong><code>${c}</code></button>`).join('')}</div></div>`}
function typePanel(){return `<div class="glass-panel">${panelHead('Una voz, bien definida.','Manrope + DM Sans',`<span class="eyebrow" style="font-size:7px">02 / TYPE</span>`)}<div class="type-specimen"><span class="letters">Aa</span><p>Claridad en cada tamaño.<br>Personalidad en cada título.<br>Precisión en cada cifra.</p></div><div class="font-line"><span>Tu próximo capítulo.</span><span>Gs. 120.000</span></div></div>`}
function buttonsPanel(){return `<div class="glass-panel">${panelHead('Acciones que invitan.','Cada clic tiene una respuesta.',`<span class="eyebrow" style="font-size:7px">03 / ACTION</span>`)}<div class="component-actions">${button('Crear reserva','new-booking','primary','plus')}${button('Vista previa','preview-portal','secondary','eye')}${button('Guardar','demo-save','white')}<button class="icon-btn" data-action="search" aria-label="Buscar">${icon('search')}</button></div><div class="component-bottom">${segmented(['Hoy','Semana','Mes'],ui.demoPeriod||'Hoy','demo-period')}<label class="switch-label"><input class="switch" type="checkbox" data-bot-toggle ${state.bot.enabled?'checked':''}>Respuesta automática</label></div></div>`}
function appearancePanel(){return `<div class="glass-panel">${panelHead('Hazlo tuyo.','El mismo sistema. Tu personalidad.',`<button class="text-btn" data-page="apariencia">Personalizar ${icon('right')}</button>`)}${palette()}<div class="appearance-preview"><div><h4>Agendatepy Studio</h4><small class="muted micro">Tu marca, en cada detalle.</small></div><div class="mini-bars"><i style="--h:10px"></i><i style="--h:17px"></i><i style="--h:13px"></i><i style="--h:25px"></i></div></div></div>`}
function catalogOverview(){return `<div class="grid cols-2">${tokensPanel()}${typePanel()}${buttonsPanel()}${appearancePanel()}</div>${sectionHead('Diseñados para el día a día.','Los componentes se conectan con datos y acciones reales del prototipo.',routeButton('Ver dashboard','resumen','secondary','grid'))}<div class="grid cols-3">${metric('cash','Ingresos de hoy',gs(todayRevenue()),'Local','Cobros registrados')}${metric('calendar','Turnos confirmados',String(todayAppointments().filter(a=>a.status==='confirmed').length),'En agenda','Una agenda, todo tu equipo')}<div class="glass-panel">${panelHead('Siempre en sintonía.','Estados claros en cada paso.')}<div class="flex" style="gap:9px;margin:22px 0 15px">${statusBadge('confirmed')}${statusBadge('pending')}${badge('WhatsApp IA','purple',true)}${badge('Cliente VIP','amber')}${statusBadge('cancelled')}</div><p class="muted micro">Color, texto y contexto. Nada queda a interpretación.</p></div></div>`}
function catalogFoundation(){return `<div class="grid cols-2">${tokensPanel()}${typePanel()}${appearancePanel()}<div class="glass-panel">${panelHead('Superficies & profundidad','Cristal ahumado, reflejos suaves, bordes precisos.')}<div class="grid cols-3" style="margin:20px 0"><div class="glass-panel" style="padding:20px 8px;border-radius:12px;text-align:center;font-size:9px">12 px</div><div class="glass-panel" style="padding:20px 8px;border-radius:22px;text-align:center;font-size:9px">22 px</div><div class="glass-panel" style="padding:20px 8px;border-radius:30px;text-align:center;font-size:9px">30 px</div></div><label class="range-head" for="foundation-blur">Desenfoque del cristal<output data-blur-label>${state.prefs.blur}px</output></label><input id="foundation-blur" type="range" min="0" max="48" value="${state.prefs.blur}" data-blur></div></div><div class="glass-panel spaced">${panelHead('Navegación con espacio para respirar.','El menú crece en horizontal. Tu contenido mantiene su lugar.')}<div class="flex">${routeButton('Finanzas','caja','secondary','cash')}${routeButton('Turnos','agenda','secondary','calendar')}${routeButton('Inteligencia','whatsapp','secondary','bolt')}${routeButton('Equipo','equipo','secondary','users')}${button('Búsqueda universal','search','primary','search')}</div></div>`}
function catalogControls(){return `<div class="grid cols-2">${buttonsPanel()}<div class="glass-panel">${panelHead('Variantes & estados','Acciones primarias, destructivas y deshabilitadas.')}<div class="component-actions">${button('Cobrar turno','pick-charge','primary','cash')}${button('Cancelar cita','pick-cancel','danger','close')}<button class="btn secondary" disabled>Sin disponibilidad</button></div><div class="component-bottom">${button('Nuevo cliente','new-client','secondary','users')}<button class="text-btn" data-page="clientes">Ver todos ${icon('right')}</button></div></div><div class="glass-panel">${panelHead('Campos que guían.','Etiquetas claras y validación antes de guardar.')}<form id="demo-form">${input('Nombre completo','name','','text','required placeholder="Ej. Santiago Acosta" maxlength="60"')}<label class="field"><span>WhatsApp</span><div class="input-shell"><span class="micro muted">PY</span><input type="tel" name="phone" data-phone placeholder="+595 981 000 000" required></div></label>${selectField('Profesional','staff',state.team.map(t=>[t.id,t.name]),'t1')}<p class="form-error" role="alert"></p>${button('Validar formulario','submit-demo','primary','check','type="submit"')}</form></div><div class="glass-panel">${panelHead('Ajustes, sin fricción.','Controles que recuerdan tus preferencias.')}<label class="setting-row"><span><strong>Animaciones suaves</strong><p>Transiciones, orbes y entrada de gráficos.</p></span><input class="switch" type="checkbox" data-pref="motion" ${state.prefs.motion?'checked':''}></label><label class="setting-row"><span><strong>Vista compacta</strong><p>Más información en menos espacio.</p></span><input class="switch" type="checkbox" data-pref="compact" ${state.prefs.compact?'checked':''}></label><label class="range-head" for="demo-commission">Comisión de ejemplo<output id="demo-commission-label">45%</output></label><input id="demo-commission" type="range" value="45" min="0" max="70"><div class="note">${icon('info')}Este control es una muestra. Las comisiones del negocio se gestionan en Equipo.</div></div><div class="glass-panel">${panelHead('Elige el momento.','Los horarios ocupados están deshabilitados.')}<div class="slot-picker">${['09:00','09:30','10:00','10:30','11:00','11:30','12:00','12:30'].map((t,i)=>`<button ${[0,1,4].includes(i)?'disabled':''} data-demo-slot="${t}" class="${ui.demoSlot===t?'selected':''}">${t}</button>`).join('')}</div><p id="demo-slot-label" class="muted small spaced">${ui.demoSlot?'Horario elegido: '+ui.demoSlot:'Selecciona un horario disponible.'}</p></div><div class="glass-panel">${panelHead('Selección & categorías','Filtros que muestran resultados al instante.')}<div class="filter-chips">${['Todos','Corte','Barba','Spa'].map(c=>`<button class="${(ui.demoFilter||'Todos')===c?'active':''}" data-demo-filter="${c}">${c}</button>`).join('')}</div><div class="stack spaced">${state.services.filter(s=>!ui.demoFilter||ui.demoFilter==='Todos'||s.category===ui.demoFilter).slice(0,3).map(s=>`<div class="between"><span class="small">${s.name}</span><span class="micro muted">${gs(s.price)}</span></div>`).join('')}</div></div></div>`}
function catalogData(){return `<div class="grid cols-3">${metric('cash','Facturación',gs(todayRevenue()),'Hoy','Ingresos de servicios y productos')}${metric('users','Clientes',String(state.clients.length),'CRM','Relaciones que crecen')}${metric('box','Productos',String(state.products.length),'Stock','Todo en su lugar')}</div><div class="grid split spaced"><div class="glass-panel">${panelHead('Turnos & estados','Una tarjeta, todo el contexto.',routeButton('Ver agenda','agenda'))}<div class="stack">${todayAppointments().filter(a=>a.status!=='paid').slice(0,2).map(appointmentCard).join('')}</div></div><div class="glass-panel">${panelHead('Inteligencia operativa','Movimiento con propósito.',badge('En vivo','purple',true))}${orb(occupancy()+'%')}<div class="orb-stats"><div><b>${todayAppointments().length}</b><small>Turnos hoy</small></div><div><b>${state.team.length}</b><small>Profesionales</small></div><div><b>${occupancy()}%</b><small>Ocupación</small></div></div></div></div><div class="glass-panel spaced">${panelHead('Movimientos & registros','Filas limpias, importes legibles y acciones directas.')}${transactionTable(state.transactions.filter(t=>t.date===TODAY).slice(0,4))}</div><div class="grid cols-2 spaced"><div class="glass-panel">${panelHead('Curvas que cuentan una historia.','Datos reales de este prototipo.')}${revenueChart(7,'catalog')}</div>${clientCard(state.clients[0])}</div>`}
function catalogFeedback(){return `<div class="grid cols-2"><div class="glass-panel">${panelHead('Una respuesta en el momento justo.','Notificaciones discretas y contextuales.')}<div class="component-actions">${button('Mostrar éxito','demo-save','primary','check')}${button('Mostrar aviso','demo-warning','secondary','info')}${button('Centro de actividad','notifications','secondary','bell')}</div><div class="alert">${icon('check')}Tu reserva quedó guardada en este navegador.</div><div class="alert warning spaced">${icon('info')}Hay un producto por debajo del stock mínimo.</div></div><div class="glass-panel">${panelHead('Conversaciones, con contexto.','La ventana se cierra con Escape y devuelve el foco.')}<div class="component-actions">${button('Nueva reserva','new-booking','primary','plus')}${button('Ficha del cliente','sample-client','secondary','users')}${button('Confirmación','demo-confirm','secondary','shield')}</div><p class="muted small">Prueba un flujo completo desde el catálogo.</p></div><div class="glass-panel">${panelHead('Un comienzo bien acompañado.','Checklist de activación del espacio.',`<div class="check-ring" style="--progress:${state.checklist.filter(Boolean).length*20}%"><span>${state.checklist.filter(Boolean).length}/5</span></div>`)}${activationChecklist()}</div><div class="glass-panel">${panelHead('Estados de carga & vacío','También cuentan cuando todavía no hay datos.')}<div class="skeleton" style="width:44%"></div><div class="skeleton" style="width:90%"></div><div class="skeleton" style="width:68%"></div>${empty('Todo al día.','Las próximas novedades aparecerán aquí.','check')}</div><div class="glass-panel">${panelHead('Detalles cuando los necesitas.','Acordeones accesibles y navegación con teclado.')}<details class="accordion" open><summary>¿Qué se guarda en este espacio?</summary><p>Reservas, clientes, movimientos, inventario y preferencias se conservan en el navegador. Exporta una copia desde Ajustes.</p></details><details class="accordion"><summary>¿WhatsApp ya está conectado?</summary><p>El chat es un simulador local. La conexión con Evolution API necesita un servidor y credenciales; no se envían mensajes externos.</p></details><details class="accordion"><summary>¿Puedo usar el modo claro?</summary><p>Sí. El botón del sol cambia todas las superficies, textos, formularios y ventanas al modo Frosty Glass.</p></details></div><div class="glass-panel">${panelHead('Progreso que se siente.','De una pequeña tarea a un gran avance.')}<div class="progress-label"><span>Configuración del espacio</span><span>${state.checklist.filter(Boolean).length*20}%</span></div>${progress(state.checklist.filter(Boolean).length*20)}<div class="spaced">${orb('5 / 5','PASOS')}</div></div></div>`}
function activationChecklist(){return `<div class="checklist">${[['Servicios creados','Tu catálogo, listo para reservar.'],['Equipo configurado','Cada profesional tiene su espacio.'],['Marca personalizada','Una experiencia que se siente tuya.'],['Portal revisado','Prueba una reserva como cliente.'],['Flujo de caja probado','Registra tu primer cobro de demostración.']].map(([n,d],i)=>`<label class="check-row"><input type="checkbox" data-checklist="${i}" ${state.checklist[i]?'checked':''}><span>${n}<small>${d}</small></span></label>`).join('')}</div>`}
function todayAppointments(){return state.appointments.filter(a=>a.date===TODAY&&a.status!=='cancelled').sort((a,b)=>a.time.localeCompare(b.time))}
function todayRevenue(){return state.transactions.filter(t=>t.date===TODAY&&t.amount>0).reduce((s,t)=>s+t.amount,0)}
function occupancy(){const booked=todayAppointments().filter(a=>a.status!=='no-show').reduce((s,a)=>s+a.duration,0),capacity=state.team.length*(minutes(state.business.close)-minutes(state.business.open));return Math.min(100,Math.round(booked/Math.max(1,capacity)*100))}
function appointmentCard(a){const c=getClient(a.clientId),t=getStaff(a.staffId);return `<article class="appointment" style="--status-color:${statusColor(a.status)}"><div class="appointment-top"><span class="appointment-time">${a.time} — ${timeLabel(minutes(a.time)+a.duration)}</span>${statusBadge(a.status)}</div><div class="person-cell"><span class="avatar ${t?.color||''}">${esc(initials(c?.name||'Cliente'))}</span><div><h3>${esc(c?.name||'Cliente')}</h3><p>${esc(a.serviceName)} · ${esc(t?.name.split(' ')[0]||'')}</p></div></div><div class="appointment-bottom"><strong>${gs(a.price)}</strong><div class="flex" style="gap:6px">${['pending','confirmed'].includes(a.status)?`<button class="btn primary" data-charge="${a.id}">${icon('cash')}Cobrar</button>`:''}<button class="icon-btn" data-appointment="${a.id}" aria-label="Ver cita de ${esc(c?.name)}">${icon('chevron')}</button></div></div></article>`}
function revenueChart(days=7,id='main'){const start=dateAdd(TODAY,-days+1),points=days>30?12:days>7?10:7,buckets=Array.from({length:points},()=>0);state.transactions.filter(t=>t.date>=start&&t.amount>0).forEach(t=>{const diff=Math.floor((new Date(t.date+'T12:00')-new Date(start+'T12:00'))/86400000);const i=Math.min(points-1,Math.floor(diff/days*points));if(i>=0)buckets[i]+=t.amount});const max=Math.max(...buckets,1),coords=buckets.map((v,i)=>[38+i*(440/(points-1)),180-v/max*130]),d=coords.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ');return `<svg class="chart" viewBox="0 0 500 224" preserveAspectRatio="none" role="img" aria-label="Ingresos registrados en los últimos ${days} días"><defs><linearGradient id="chart-fill-${id}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="var(--primary)" stop-opacity=".2"/><stop offset="1" stop-color="var(--primary)" stop-opacity="0"/></linearGradient></defs>${[50,95,140,185].map(y=>`<path class="grid-line" d="M38 ${y}H480"/>`).join('')}<path d="${d}L478 190H38Z" fill="url(#chart-fill-${id})"/><path class="series" d="${d}"/>${coords.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3" fill="var(--primary)"><title>${dateLabel(dateAdd(start,Math.floor(i*days/points)),true)}: ${gs(buckets[i])}</title></circle>`).join('')}${[0,Math.floor((points-1)/2),points-1].map(i=>`<text x="${coords[i][0]}" y="216" text-anchor="${i===0?'start':i===points-1?'end':'middle'}">${dateLabel(dateAdd(start,Math.min(days-1,Math.floor(i*days/points))),true)}</text>`).join('')}<text x="1" y="54">${max>=1000000?(max/1000000).toFixed(1)+'m':Math.round(max/1000)+'k'}</text><text x="4" y="190">0</text></svg>`}
function dashboardView(){const appts=todayAppointments(),revenue=todayRevenue(),paid=appts.filter(a=>a.status==='paid').length;return `${title('TU NEGOCIO, EN SINTONÍA','Un buen día empieza aquí.','Todo lo que importa, en un solo vistazo.',`${segmented(['Finanzas','Turnos','IA','Equipo'],'Turnos','space')}${routeButton('Nueva reserva','reserva','primary','plus')}`)}<div class="grid cols-4">${metric('cash','Ingresos de hoy',gs(revenue),'Hoy',`${state.transactions.filter(t=>t.date===TODAY&&t.amount>0).length} cobros registrados`)}${metric('calendar','Turnos del día',String(appts.length),'Agenda',`${paid} atendidos · ${appts.length-paid} restantes`)}${metric('users','Clientes',String(state.clients.length),'CRM','Tu comunidad sigue creciendo')}${metric('chart','Ocupación',occupancy()+'%','Equipo','Disponibilidad en tiempo real')}</div><div class="grid split spaced"><div class="glass-panel">${panelHead('El pulso de tu negocio','Ingresos registrados durante la última semana',routeButton('Ver métricas','metricas','secondary','chart'))}${revenueChart(7,'dashboard')}<div class="chart-legend"><span>Ingresos</span><span>Guaraníes · últimos 7 días</span></div></div><div class="glass-panel featured">${panelHead('Un equipo en movimiento.','Cada turno cuenta.',badge('Hoy','orange',true))}${orb(occupancy()+'%')}<div class="orb-stats"><div><b>${appts.length}</b><small>Reservas</small></div><div><b>${state.team.length}</b><small>Profesionales</small></div><div><b>${paid}</b><small>Atendidos</small></div></div></div></div>${sectionHead('Lo que viene hoy.',dateLabel(TODAY),routeButton('Ver agenda','agenda','secondary','right'))}<div class="grid cols-3">${appts.filter(a=>['confirmed','pending'].includes(a.status)).slice(0,3).map(appointmentCard).join('')||empty('Tu agenda está libre.','Crea una reserva para comenzar.')}</div><div class="grid cols-2 spaced"><div class="glass-panel">${panelHead('Tu asistente, siempre cerca.','Simulación de conversación local.',badge(state.bot.enabled?'Activo':'En pausa','purple',state.bot.enabled))}<div class="between"><div><h2>${state.chat.filter(c=>c.role==='client').length} conversaciones</h2><p class="muted small spaced">Prueba horarios, servicios y preguntas frecuentes.</p></div>${routeButton('Probar asistente','whatsapp','primary','message')}</div></div><div class="glass-panel">${panelHead('Pequeños pasos. Gran comienzo.','Completa tu espacio.',`<div class="check-ring" style="--progress:${state.checklist.filter(Boolean).length*20}%"><span>${state.checklist.filter(Boolean).length}/5</span></div>`)}${activationChecklist()}</div></div>`}
function agendaView(){const list=state.appointments.filter(a=>a.date===ui.date&&(ui.staff==='all'||a.staffId===ui.staff)).sort((a,b)=>a.time.localeCompare(b.time));return `${title('OPERACIONES / AGENDA','Cada momento, en su lugar.','Organiza los turnos de tu equipo sin perder el ritmo.',`${button('Bloquear horario','block-time','secondary','lock')}${routeButton('Nueva reserva','reserva','primary','plus')}`)}<div class="glass-panel"><div class="calendar-toolbar"><div class="calendar-date"><button class="icon-btn" data-date-offset="-1" aria-label="Día anterior">${icon('arrowLeft')}</button><h2>${dateLabel(ui.date)}</h2><button class="icon-btn" data-date-offset="1" aria-label="Día siguiente">${icon('right')}</button></div><div class="flex">${segmented(['Día','Semana','Lista'],ui.agendaView,'agenda')}<select class="input-glass" style="width:160px;font-size:10px;padding:8px" aria-label="Filtrar profesional" data-agenda-staff><option value="all">Todo el equipo</option>${state.team.map(t=>`<option value="${t.id}" ${ui.staff===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><input class="input-glass" style="width:140px;font-size:10px;padding:8px" type="date" value="${ui.date}" aria-label="Fecha de agenda" data-agenda-date></div></div>${ui.agendaView==='Día'?scheduleGrid():ui.agendaView==='Semana'?weekView():`<div class="grid cols-3">${list.map(appointmentCard).join('')||empty('Sin citas para esta fecha.','Elige otro día o crea una reserva.','calendar')}</div>`}</div><div class="note spaced">${icon('info')}Arrastra las citas sin cobrar a otro bloque para reprogramarlas. La duración del servicio y los horarios ocupados se validan automáticamente.</div>`}
function scheduleGrid(){const staff=state.team.filter(t=>ui.staff==='all'||t.id===ui.staff),start=minutes(state.business.open),end=minutes(state.business.close);let html=`<div class="schedule"><div class="schedule-grid" style="--staff-count:${staff.length}"><div class="schedule-head">HORA</div>${staff.map(t=>`<div class="schedule-head"><span class="person-cell"><span class="avatar small-avatar ${t.color}">${initials(t.name)}</span>${esc(t.name)}</span></div>`).join('')}`;for(let n=start;n<end;n+=30){let time=timeLabel(n);html+=`<div class="schedule-time">${time}</div>`+staff.map(t=>{const a=state.appointments.find(a=>a.staffId===t.id&&a.date===ui.date&&!['cancelled','no-show'].includes(a.status)&&minutes(a.time)>=n&&minutes(a.time)<n+30),occupied=state.appointments.find(a=>a.staffId===t.id&&a.date===ui.date&&!['cancelled','no-show'].includes(a.status)&&minutes(a.time)<n&&minutes(a.time)+a.duration>n),block=state.blocks.find(b=>b.staffId===t.id&&b.date===ui.date&&minutes(b.start)<n+30&&minutes(b.end)>n);return `<div class="schedule-slot" data-drop-staff="${t.id}" data-drop-time="${time}">${a?`<button class="slot-event" draggable="${a.status!=='paid'}" data-drag-appointment="${a.id}" data-appointment="${a.id}" style="--event-color:${statusColor(a.status)}"><strong>${esc(getClient(a.clientId)?.name)}</strong><small>${a.time} · ${esc(a.serviceName)}</small>${statusBadge(a.status)}</button>`:occupied?`<span class="micro muted" style="padding:9px">En servicio · ${timeLabel(minutes(occupied.time)+occupied.duration)}</span>`:block?`<button class="slot-event" style="--event-color:var(--subtle)" data-unblock="${block.id}"><strong>${icon('lock')} ${esc(block.reason)}</strong><small>${block.start}–${block.end} · quitar</small></button>`:`<button class="slot-add" style="border:0;background:none;width:100%;cursor:pointer;pointer-events:auto" data-book-slot="${time}" data-book-staff="${t.id}" aria-label="Reservar ${time} con ${esc(t.name)}">+</button>`}</div>`}).join('')}return html+'</div></div>'}
function weekView(){const day=new Date(ui.date+'T12:00').getDay(),monday=dateAdd(ui.date,-((day+6)%7));return `<div class="table-wrap"><div class="week-grid">${Array.from({length:7},(_,i)=>{const date=dateAdd(monday,i),list=state.appointments.filter(a=>a.date===date&&(ui.staff==='all'||a.staffId===ui.staff)&&a.status!=='cancelled').sort((a,b)=>a.time.localeCompare(b.time));return `<div class="week-column"><h3>${dateLabel(date,true)}</h3>${list.map(a=>`<button class="slot-event" style="--event-color:${statusColor(a.status)}" data-appointment="${a.id}"><strong>${a.time} · ${esc(getClient(a.clientId)?.name)}</strong><small>${esc(a.serviceName)}</small></button>`).join('')||'<p class="muted micro">Disponible</p>'}<button class="text-btn spaced" data-week-date="${date}">Ver día ${icon('right')}</button></div>`}).join('')}</div></div>`}
function bookingView(publicMode=false){const b=ui.booking,s=getService(b.serviceId),client=getClient(b.clientId),t=getStaff(b.staffId);return `${title(publicMode?'TU PRÓXIMO MOMENTO':'OPERACIONES / NUEVA RESERVA',publicMode?'Un momento para ti.':'Hagamos espacio para alguien.',publicMode?'Elige tu servicio, encuentra tu horario y déjanos el resto.':'Una reserva sencilla, de principio a fin.',publicMode?badge('Portal local de demostración','orange'):routeButton('Volver a agenda','agenda','secondary','arrowLeft'))}${publicMode?portalBanner():''}<div class="grid split"><div class="glass-panel"><div class="booking-steps">${['Servicio','Horario','Confirmación'].map((label,i)=>`<span class="booking-step ${b.step===i?'active':''}"><b>${i<b.step?'✓':i+1}</b>${label}</span>`).join('')}</div>${b.step===0?`<div class="stack">${state.services.filter(s=>s.active).map(s=>serviceOption(s,b.serviceId===s.id)).join('')}</div>`:b.step===1?`<div class="grid cols-2">${selectField('Profesional','booking-staff',[['any','Cualquiera disponible'],...state.team.filter(t=>s?.staff.includes(t.id)).map(t=>[t.id,t.name])],b.staffId,'data-booking-staff')}${input('Día de la cita','booking-date',b.date,'date',`data-booking-date min="${TODAY}" required`)}</div><div class="between"><h3>Horarios disponibles</h3>${badge(`${s?.duration||0} min`,'orange')}</div><div class="slot-picker">${bookingSlots()}</div><p class="muted micro spaced">Los horarios tachados no tienen disponibilidad para este servicio.</p>`:`<form id="booking-form" data-public="${publicMode}">${!publicMode?selectField('Cliente','clientId',[...state.clients.map(c=>[c.id,c.name]),['new','+ Crear un cliente nuevo']],b.clientId,'data-booking-client'):''}<div id="new-client-fields" ${!publicMode&&b.clientId!=='new'?'hidden':''}>${input('Nombre completo','name',b.name,'text',`${publicMode||b.clientId==='new'?'required':''} maxlength="60" placeholder="Tu nombre"`)}<label class="field"><span>WhatsApp</span><div class="input-shell"><span class="micro muted">PY</span><input name="phone" data-phone type="tel" value="${esc(b.phone||'+595 ')}" ${publicMode||b.clientId==='new'?'required':''} placeholder="+595 981 000 000"></div></label></div>${publicMode?`<label class="field"><span>Comprobante (opcional)</span><input type="file" name="receipt" accept="image/*,.pdf"><small>Se registra el nombre del archivo. No se envía a ningún servidor.</small></label>`:''}<div class="note">${icon('shield')}La reserva se guarda en este dispositivo. No se envían mensajes ni se realizan pagos externos.</div><p class="form-error" role="alert"></p><div class="dialog-actions"><button class="btn secondary" type="button" data-booking-back>Volver</button><button type="submit" class="btn primary">${icon('check')}Confirmar reserva</button></div></form>`}${b.step<2?`<div class="dialog-actions">${b.step?'<button class="btn secondary" data-booking-back>Volver</button>':''}<button class="btn primary" data-booking-next ${b.step===1&&!b.time?'disabled':''}>Continuar ${icon('right')}</button></div>`:''}</div><aside class="glass-panel booking-summary featured">${panelHead('Tu reserva','Los detalles, siempre a la vista.',icon('calendar'))}<div class="summary-line"><span>Servicio</span><b>${esc(s?.name||'Elige un servicio')}</b></div><div class="summary-line"><span>Duración</span><b>${s?.duration||'—'} min</b></div><div class="summary-line"><span>Profesional</span><b>${esc(t?.name||'Cualquiera disponible')}</b></div><div class="summary-line"><span>Fecha</span><b>${dateLabel(b.date,true)}</b></div><div class="summary-line"><span>Hora</span><b>${b.time||'Por elegir'}</b></div>${!publicMode&&b.clientId!=='new'?`<div class="summary-line"><span>Cliente</span><b>${esc(client?.name||'Por elegir')}</b></div>`:''}<div class="summary-total"><span>Total del servicio</span><strong>${gs(s?.price||0)}</strong></div><p class="muted micro spaced">Pago en el local · sin cargos online</p></aside></div>`}
function serviceOption(s,selected=false,preview=false){return `<button class="service-option ${selected?'selected':''}" ${preview?'data-page="portal"':`data-book-service="${s.id}"`} aria-pressed="${selected}"><span class="service-glyph">${icon(s.category==='Spa'?'star':'scissors')}</span><span><strong>${esc(s.name)}</strong><small>${s.duration} min · ${esc(s.category)}</small></span><span class="service-price">${gs(s.price)}</span></button>`}
function bookingSlots(){const b=ui.booking,result=[];for(let n=minutes(state.business.open);n<minutes(state.business.close);n+=30){const time=timeLabel(n),available=availableStaff(b.serviceId,b.staffId,b.date,time).length>0;result.push(`<button data-book-time="${time}" class="${b.time===time?'selected':''}" ${available?'':'disabled'} aria-pressed="${b.time===time}">${time}</button>`)}return result.join('')}
function transactionTable(items){return `<div class="table-wrap"><table><thead><tr><th>Movimiento</th><th>Cliente</th><th>Fecha</th><th>Método</th><th style="text-align:right">Monto</th><th></th></tr></thead><tbody>${items.map(t=>`<tr><td><strong>${esc(t.name)}</strong><small>${t.type==='expense'?'Egreso':t.type==='product'?'Producto':'Servicio'} · ${esc(t.time)}</small></td><td>${esc(getClient(t.clientId)?.name||'Mostrador')}</td><td>${dateLabel(t.date,true)}</td><td>${badge(t.method,t.method==='Efectivo'?'green':t.method==='POS'?'amber':'purple')}</td><td style="text-align:right" class="${t.amount<0?'negative':''}"><strong>${gs(t.amount)}</strong></td><td><button class="icon-btn" data-receipt="${t.id}" aria-label="Ver comprobante">${icon('file')}</button></td></tr>`).join('')}</tbody></table>${items.length?'':empty('No hay movimientos para este filtro.','','cash')}</div>`}
function cashView(){const todayTx=state.transactions.filter(t=>t.date===TODAY),byMethod=m=>todayTx.filter(t=>t.method===m&&t.amount>0).reduce((a,t)=>a+t.amount,0),filtered=state.transactions.filter(t=>(ui.txnMethod==='Todos'||t.method===ui.txnMethod)&&(t.name+' '+(getClient(t.clientId)?.name||'')).toLowerCase().includes(ui.txnQuery.toLowerCase()));return `${title('FINANZAS / CAJA','Tus números, bien claros.','Cada ingreso, cada movimiento, cada cierre.',`${badge(state.cash.open?'Caja abierta':'Caja cerrada',state.cash.open?'green':'red',state.cash.open)}${button(state.cash.open?'Cerrar caja':'Abrir caja',state.cash.open?'close-cash':'open-cash','secondary','cash')}${button('Registrar egreso','new-expense','primary','plus')}`)}<div class="grid cols-3">${metric('cash','Efectivo en caja',gs(cashTotal()),'Disponible','Base inicial: '+gs(state.cash.initial))}${metric('card','Tarjeta & POS',gs(byMethod('POS')),'Hoy','Cobros registrados en terminal')}${metric('wallet','Transferencias',gs(byMethod('Transferencia')),'Hoy','Registros manuales del día')}</div><div class="glass-panel spaced">${panelHead('Movimientos de caja','Registros locales de demostración.',button('Exportar CSV','export-transactions','secondary','download'))}<div class="toolbar"><div class="input-shell">${icon('search')}<input type="search" data-txn-search value="${esc(ui.txnQuery)}" placeholder="Buscar movimiento o cliente" aria-label="Buscar movimientos"></div><div class="filter-chips">${['Todos','Efectivo','POS','Transferencia'].map(m=>`<button data-txn-method="${m}" class="${m===ui.txnMethod?'active':''}">${m}</button>`).join('')}</div></div><div id="transaction-results">${transactionTable(filtered.slice(0,35))}</div></div>${sectionHead('Turnos pendientes de cobro.')}<div class="grid cols-3">${todayAppointments().filter(a=>['confirmed','pending'].includes(a.status)).map(appointmentCard).join('')||empty('No quedan cobros pendientes.','','check')}</div>`}
function clientCard(c){return `<article class="glass-panel client-card"><div class="client-top"><span class="avatar ${c.tag==='VIP'?'purple':'green'}">${esc(initials(c.name))}</span><div><h3>${esc(c.name)}</h3><p>${esc(c.phone)}</p></div>${badge(c.tag,c.tag==='VIP'?'amber':c.tag==='En riesgo'?'red':'green')}</div><p class="client-note">${esc(c.notes||'Sin notas todavía. Cada visita es una nueva oportunidad.')}</p><div class="client-stats"><div><strong>${c.visits}</strong><small>Visitas</small></div><div><strong>${gs(c.spent)}</strong><small>Acumulado</small></div><div><strong>${c.points}</strong><small>Puntos</small></div></div><div class="between"><button class="text-btn" data-client="${c.id}">Abrir ficha ${icon('right')}</button><button class="icon-btn" data-message-client="${c.id}" aria-label="Preparar mensaje para ${esc(c.name)}">${icon('message')}</button></div></article>`}
function clientsView(){return `${title('RELACIONES / CRM','Conoce a quienes vuelven.','Más que nombres. Historias, preferencias y próximos encuentros.',button('Nuevo cliente','new-client','primary','plus'))}<div class="toolbar"><div class="input-shell">${icon('search')}<input data-client-search type="search" value="${esc(ui.clientQuery)}" placeholder="Buscar nombre o WhatsApp" aria-label="Buscar clientes"></div><div class="filter-chips">${['Todos','VIP','Frecuente','Nuevo','En riesgo'].map(f=>`<button data-client-filter="${f}" class="${ui.clientFilter===f?'active':''}">${f}</button>`).join('')}</div></div><div class="grid cols-3" id="client-results">${clientResults()}</div>`}
function clientResults(){return state.clients.filter(c=>(ui.clientFilter==='Todos'||c.tag===ui.clientFilter)&&(c.name+' '+c.phone).toLowerCase().includes(ui.clientQuery.toLowerCase())).map(clientCard).join('')||empty('No encontramos clientes.','Prueba con otro nombre o etiqueta.','users')}
function servicesView(){const list=state.services.filter(s=>ui.serviceFilter==='Todos'||s.category===ui.serviceFilter);return `${title('TU NEGOCIO / SERVICIOS','Tu talento, en un catálogo.','Precios claros, tiempos definidos y una experiencia consistente.',button('Crear servicio','new-service','primary','plus'))}<div class="toolbar"><div class="filter-chips">${['Todos',...new Set(state.services.map(s=>s.category))].map(c=>`<button data-service-filter="${esc(c)}" class="${ui.serviceFilter===c?'active':''}">${esc(c)}</button>`).join('')}</div><span class="muted micro">${state.services.filter(s=>s.active).length} servicios visibles en el portal</span></div><div class="grid cols-3">${list.map(s=>`<article class="glass-panel service-card"><div class="service-art">${icon(s.category==='Spa'?'star':s.category==='Color'?'palette':'scissors')}</div><div class="between"><h3>${esc(s.name)}</h3>${badge(s.category,'orange')}</div><div class="product-stats"><span>${icon('clock')} ${s.duration} minutos</span><b>${gs(s.price)}</b></div><p class="muted micro">${s.staff.map(id=>esc(getStaff(id)?.name.split(' ')[0]||'')).join(' · ')}</p><div class="setting-row"><label class="switch-label"><input class="switch" type="checkbox" data-service-active="${s.id}" ${s.active?'checked':''}>Visible en el portal</label><button class="icon-btn" data-edit-service="${s.id}" aria-label="Editar ${esc(s.name)}">${icon('edit')}</button></div><div class="between spaced"><button class="text-btn" data-move-service="${s.id}" aria-label="Mover ${esc(s.name)} al inicio">Mover al inicio ${icon('arrow')}</button><button class="text-btn" data-reserve-service="${s.id}">Reservar ${icon('right')}</button></div></article>`).join('')}</div>`}
function productsView(){return `${title('TU NEGOCIO / INVENTARIO','Pequeños productos. Grandes detalles.','Stock, precios y ventas de mostrador en el mismo lugar.',button('Nuevo producto','new-product','primary','plus'))}${state.products.some(p=>p.stock<=p.min)?`<div class="alert warning" style="margin-bottom:18px">${icon('info')}Hay ${state.products.filter(p=>p.stock<=p.min).length} producto(s) por debajo del stock recomendado.</div>`:''}<div class="grid cols-3">${state.products.map(p=>`<article class="glass-panel"><div class="product-art">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}">`:`<div class="bottle ${p.type==='jar'?'jar':''}"><span>STUDIO<br>${p.type==='jar'?'MATTE CLAY':'BOTANICAL'}</span></div>`}${badge(p.stock<=p.min?'Stock bajo':'Disponible',p.stock<=p.min?'amber':'green')}</div><div class="between"><h3>${esc(p.name)}</h3><button class="icon-btn" data-edit-product="${p.id}" aria-label="Editar producto">${icon('edit')}</button></div><p class="muted micro" style="margin-top:5px">${esc(p.category)} · Costo ${gs(p.cost)}</p><div class="product-stats"><span>${p.stock} unidades · mín. ${p.min}</span><strong class="accent">${gs(p.price)}</strong></div>${progress(Math.min(100,p.stock/(p.min*4)*100))}<div class="between spaced"><button class="text-btn" data-stock="${p.id}">Ajustar stock</button><button class="btn primary" data-sell="${p.id}" ${p.stock<1?'disabled':''}>${icon('bag')}Vender</button></div><button class="text-btn spaced" data-product-image="${p.id}">${icon('image')}Cambiar imagen</button></article>`).join('')}</div><div class="note spaced">${icon('info')}Las imágenes se guardan en este dispositivo. El recorte automático por IA requiere un servicio externo; aquí puedes cargar directamente un PNG transparente.</div>`}
function chatMessages(){return state.chat.map(m=>`<div class="chat-bubble ${m.role}">${esc(m.text)}<small>${m.role==='bot'?'Asistente · simulación local':'Tú'}</small></div>`).join('')}
function whatsappView(){return `${title('AUTOMATIZACIÓN / WHATSAPP IA','Siempre cerca de tus clientes.','Diseña la conversación. Prueba el recorrido.',badge('Simulador local · sin conexión externa','purple'))}<div class="grid split"><div class="glass-panel">${panelHead('Tu asistente de reservas','Respuestas de ejemplo basadas en tus servicios.',`<label class="switch-label"><input type="checkbox" class="switch" data-bot-toggle ${state.bot.enabled?'checked':''}>${state.bot.enabled?'Activo':'En pausa'}</label>`)}<div class="chat-preview" id="chat-messages" style="min-height:320px">${chatMessages()}</div><form class="chat-form" id="chat-form"><input name="message" placeholder="Pregunta por un servicio o un horario…" required maxlength="500" aria-label="Mensaje al simulador"><button class="icon-btn" type="submit" aria-label="Enviar mensaje al simulador">${icon('send')}</button></form><div class="flex spaced">${button('Ver servicios','chat-services','secondary','scissors')}${button('Consultar horarios','chat-hours','secondary','clock')}${routeButton('Crear reserva','reserva','primary','plus')}</div></div><div class="stack"><div class="glass-panel featured">${panelHead('Inteligencia con tu esencia.','Una conversación que se siente propia.')}${orb(state.bot.enabled?'ON':'OFF','ASISTENTE')}<div class="orb-stats"><div><b>${state.chat.filter(m=>m.role==='client').length}</b><small>Mensajes de prueba</small></div><div><b>${state.services.filter(s=>s.active).length}</b><small>Servicios</small></div></div></div><div class="glass-panel">${panelHead('Conexión WhatsApp','Evolution API',badge('No conectado','amber'))}<p class="muted small" style="line-height:1.8">Este catálogo no contiene un servidor ni una sesión de WhatsApp. La conexión real necesita un backend seguro que genere el QR.</p>${button('Ver requisitos de conexión','integration-info','secondary full spaced','info')}</div></div></div><div class="glass-panel spaced">${panelHead('Tu voz. Tus recordatorios.','La plantilla se guarda para el prototipo.')}<form id="bot-settings-form"><div class="grid cols-2">${selectField('Tono del asistente','tone',[['cercano','Cercano y cálido'],['formal','Formal y profesional']],state.bot.tone)}<div><label class="setting-row"><span><strong>Recordatorio 24 horas antes</strong></span><input type="checkbox" name="reminder24" class="switch" ${state.bot.reminder24?'checked':''}></label><label class="setting-row"><span><strong>Recordatorio 2 horas antes</strong></span><input type="checkbox" name="reminder2" class="switch" ${state.bot.reminder2?'checked':''}></label></div></div><label class="field"><span>Plantilla · {cliente}, {fecha}, {hora}</span><textarea name="template" required maxlength="500">${esc(state.bot.template)}</textarea></label><button class="btn primary" type="submit">Guardar configuración</button></form></div>`}
function teamView(){return `${title('PERSONAS / EQUIPO','El talento que hace la diferencia.','Comisiones transparentes y cada aporte en su lugar.',button('Añadir profesional','new-staff','primary','plus'))}<div class="grid cols-3">${state.team.map(t=>{const due=dueFor(t.id),entries=state.transactions.filter(x=>x.staffId===t.id&&!x.settled&&x.amount>0);return `<article class="glass-panel staff-card"><div class="staff-profile"><span class="avatar ${t.color}">${initials(t.name)}</span><h3>${esc(t.name)}</h3><p>${esc(t.role)}</p>${badge('En el equipo','green',true)}</div><span class="eyebrow" style="font-size:8px">COMISIONES PENDIENTES</span><div class="commission-value">${gs(due)}</div><div class="summary-line"><span>Servicios</span><b>${t.commission}%</b></div><div class="summary-line"><span>Productos</span><b>${t.productCommission}%</b></div><div class="summary-line"><span>Operaciones sin liquidar</span><b>${entries.length}</b></div><div class="between spaced"><button class="icon-btn" data-edit-staff="${t.id}" aria-label="Editar ${esc(t.name)}">${icon('settings')}</button><button class="btn primary" data-settle="${t.id}" ${due<=0?'disabled':''}>Liquidar ${icon('right')}</button></div></article>`}).join('')}</div><div class="glass-panel spaced">${panelHead('Historial de liquidaciones','Comprobantes disponibles para imprimir o guardar como PDF.')}<div class="table-wrap"><table><thead><tr><th>Profesional</th><th>Fecha</th><th>Operaciones</th><th>Monto</th><th></th></tr></thead><tbody>${state.payouts.map(p=>`<tr><td>${esc(getStaff(p.staffId)?.name)}</td><td>${dateLabel(p.date,true)}</td><td>${p.entries.length}</td><td>${gs(p.total)}</td><td><button class="text-btn" data-payout="${p.id}">Ver recibo ${icon('file')}</button></td></tr>`).join('')}</tbody></table>${state.payouts.length?'':empty('Todavía no hay liquidaciones.','Las comisiones se calculan al registrar cada cobro.','file')}</div></div>`}
function metricsView(){const list=txnsInPeriod(ui.period),income=list.filter(t=>t.amount>0).reduce((a,t)=>a+t.amount,0),count=list.filter(t=>t.amount>0).length,expense=-list.filter(t=>t.amount<0).reduce((a,t)=>a+t.amount,0),appts=state.appointments.filter(a=>a.date>=dateAdd(TODAY,-ui.period+1)&&a.date<=TODAY),noShow=appts.length?Math.round(appts.filter(a=>a.status==='no-show').length/appts.length*100):0;return `${title('FINANZAS / MÉTRICAS','Una perspectiva más clara.','Decisiones con contexto, datos y un poco de distancia.',`${segmented(['7D','30D','Año'],ui.period===7?'7D':ui.period===30?'30D':'Año','metrics')}${button('Exportar CSV','export-report','secondary','download')}`)}<div class="grid cols-4">${metric('cash','Ingresos',gs(income),'Periodo',`${count} operaciones`)}${metric('card','Ticket promedio',gs(count?income/count:0),'Media','Por operación de venta')}${metric('arrow','Egresos',gs(expense),'Periodo','Salidas registradas')}${metric('calendar','Ausentismo',noShow+'%','No-show',`${appts.filter(a=>a.status==='no-show').length} ausencias registradas`)}</div><div class="grid split spaced"><div class="glass-panel">${panelHead('Evolución de ingresos',`Últimos ${ui.period} días · guaraníes`)}${revenueChart(ui.period,'metrics')}</div><div class="glass-panel">${panelHead('Servicios que destacan','Ingresos registrados en el periodo')}${state.services.map(s=>({s,total:list.filter(t=>t.name===s.name&&t.type==='service').reduce((a,t)=>a+t.amount,0)})).sort((a,b)=>b.total-a.total).slice(0,5).map(({s,total})=>`<div style="margin-top:17px"><div class="progress-label"><span>${esc(s.name)}</span><b>${gs(total)}</b></div>${progress(income?total/income*100:0)}</div>`).join('')}</div></div><div class="glass-panel spaced">${panelHead('Horas con más movimiento','Intensidad de citas registradas por día de la semana.')}<div class="heatmap"><span></span>${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(x=>`<span>${x}</span>`).join('')}${[9,11,13,15,17].map(h=>`<span>${h}h</span>${Array.from({length:7},(_,d)=>{let n=appts.filter(a=>((new Date(a.date+'T12:00').getDay()+6)%7)===d&&minutes(a.time)>=h*60&&minutes(a.time)<(h+2)*60).length;return `<button class="heat-cell" style="--heat:${Math.min(.8,.04+n*.15)}" data-heat="${n} cita(s) · ${['lunes','martes','miércoles','jueves','viernes','sábado','domingo'][d]}, ${h}:00–${h+2}:00" aria-label="${n} citas ${h}:00 a ${h+2}:00">${n}</button>`}).join('')}`).join('')}</div></div>`}
function loyaltyView(){const c=getClient(ui.loyalClient)||state.clients[0];return `${title('RELACIONES / FIDELIZACIÓN','Volver tiene su recompensa.','Pequeños gestos que construyen grandes relaciones.',`<select class="input-glass" style="width:205px" data-loyal-client aria-label="Seleccionar cliente">${state.clients.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`)}<div class="grid split"><div class="glass-panel featured">${panelHead('Tu próxima visita, más cerca.',esc(c.name),badge(c.tag,c.tag==='VIP'?'amber':'green'))}<p class="eyebrow">TARJETA DE SELLOS</p><div class="stamps">${Array.from({length:8},(_,i)=>`<span class="stamp ${i<c.stamps?'filled':''}">${i<c.stamps?icon('check'):String(i+1).padStart(2,'0')}</span>`).join('')}</div><div class="between"><div><h2>${c.stamps} / 8 sellos</h2><p class="muted small spaced">Ocho visitas. Un corte de regalo.</p></div><button class="btn primary" data-redeem="stamps" ${c.stamps<8?'disabled':''}>Canjear corte ${icon('gift')}</button></div><div class="note spaced">${icon('info')}Cada servicio cobrado suma un sello. Los canjes quedan registrados para este cliente.</div></div><div class="glass-panel">${panelHead('Puntos para disfrutar.','Tu lealtad, en números.',icon('star'))}<strong class="metric-value" style="font-size:43px">${c.points}</strong><p class="muted small spaced">10 puntos por cada Gs. 10.000 cobrados.</p><div class="spaced">${button('Añadir puntos','add-points','secondary','plus')}${button('Descargar tarjeta','download-loyalty','secondary spaced','download')}</div></div></div>${sectionHead('Elige tu próxima recompensa.')}<div class="grid cols-2"><div class="reward"><span class="reward-icon">${icon('scissors')}</span><span><strong>Perfilado de barba</strong><small>300 puntos · un detalle para ti</small></span><button class="btn secondary" data-redeem="barba" ${c.points<300?'disabled':''}>Canjear</button></div><div class="reward"><span class="reward-icon">${icon('star')}</span><span><strong>Ritual de spa capilar</strong><small>600 puntos · tiempo para cuidarte</small></span><button class="btn secondary" data-redeem="spa" ${c.points<600?'disabled':''}>Canjear</button></div></div><div class="glass-panel spaced">${panelHead('Tus recompensas','Historial de canjes')}${state.redemptions.filter(r=>r.clientId===c.id).map(r=>`<div class="summary-line"><span>${dateLabel(r.date,true)}</span><b>${esc(r.name)}</b>${badge('Canjeado','green')}</div>`).join('')||empty('Tu primera recompensa te espera.','','gift')}</div>`}
function portalBanner(){return `<div class="portal-banner">${state.business.banner?`<img class="banner-img" src="${esc(state.business.banner)}" alt="">`:''}${state.business.logo?`<img class="portal-logo" src="${esc(state.business.logo)}" alt="Logo del negocio">`:'<span class="brand-mark">a<span>•</span></span>'}<h2>${esc(state.business.name)}</h2><p>${esc(state.business.subtitle)}</p></div>`}
function appearanceView(){return `${title('DESIGN SYSTEM / APARIENCIA','Se siente como tu marca.','Ajusta el cristal, el color y los pequeños detalles que te hacen diferente.',button('Restaurar apariencia','reset-appearance','secondary','refresh'))}<div class="grid cols-2"><div class="stack"><div class="glass-panel">${panelHead('Tu acento, en todo el sistema.','Seis personalidades y una paleta infinita.')}${palette()}<div class="setting-row"><span><strong>Modo de apariencia</strong><p>Obsidian Glass / Frosty Glass</p></span>${segmented(['Oscuro','Claro'],state.prefs.theme==='dark'?'Oscuro':'Claro','theme')}</div><label class="range-head" for="appearance-blur">Desenfoque del cristal<output data-blur-label>${state.prefs.blur}px</output></label><input id="appearance-blur" type="range" value="${state.prefs.blur}" min="0" max="48" data-blur>${selectField('Tipografía de títulos','font',[['Manrope','Manrope · geométrica'],['DM Sans','DM Sans · cercana']],state.prefs.font,'data-font')}<label class="setting-row"><span><strong>Animaciones</strong><p>Respetamos también la preferencia del dispositivo.</p></span><input class="switch" data-pref="motion" type="checkbox" ${state.prefs.motion?'checked':''}></label><label class="setting-row"><span><strong>Vista compacta</strong></span><input class="switch" data-pref="compact" type="checkbox" ${state.prefs.compact?'checked':''}></label></div><div class="glass-panel">${panelHead('La primera impresión.','Tu identidad en el portal de reservas.')}<form id="brand-form">${input('Nombre del negocio','name',state.business.name,'text','required maxlength="45"')}${input('Mensaje de bienvenida','subtitle',state.business.subtitle,'text','required maxlength="100"')}<button class="btn primary" type="submit">Guardar identidad</button></form><div class="appearance-upload"><div><strong>Logo del negocio</strong><small>PNG, JPG o WebP · hasta 1 MB</small></div>${button('Subir logo','upload-logo','secondary','upload')}</div><div class="appearance-upload"><div><strong>Banner de bienvenida</strong><small>Imagen horizontal · hasta 1 MB</small></div>${button('Subir banner','upload-banner','secondary','image')}</div></div></div><div class="glass-panel">${panelHead('Tu portal, en vivo.','La vista previa refleja tus cambios.',segmented(['Móvil','Desktop'],ui.preview==='mobile'?'Móvil':'Desktop','preview'))}<div class="portal-preview ${ui.preview==='desktop'?'desktop':''}"><div class="device-notch"></div>${portalBanner()}<p class="eyebrow" style="font-size:7px;margin-bottom:13px">ELIGE TU SERVICIO</p>${state.services.filter(s=>s.active).slice(0,3).map(s=>serviceOption(s,false,true)).join('')}<div class="spaced">${routeButton('Reservar mi momento','portal','primary full','right')}</div><p class="micro muted" style="text-align:center;margin-top:13px">${esc(state.business.address)}</p></div></div></div>`}
function settingsView(){return `${title('CONFIGURACIÓN / NEGOCIO','Un espacio que funciona para ti.','Tu información, tus horarios y tus preferencias.',button('Exportar mis datos','export-data','secondary','download'))}<div class="grid cols-2"><div class="glass-panel">${panelHead('Información del negocio','Se muestra en tu portal local.')}<form id="business-form">${input('Nombre','name',state.business.name,'text','required maxlength="45"')}${input('WhatsApp del negocio','phone',state.business.phone,'tel','required data-phone')}${input('Dirección','address',state.business.address,'text','required maxlength="120"')}<div class="grid cols-2">${input('Apertura','open',state.business.open,'time','required')}${input('Cierre','close',state.business.close,'time','required')}</div><p class="form-error" role="alert"></p><button class="btn primary" type="submit">Guardar ajustes</button></form></div><div class="stack"><div class="glass-panel">${panelHead('Tu información, contigo.','Todo se conserva en este navegador.')}<p class="muted small" style="line-height:1.9">Este es un prototipo funcional con datos de demostración. Agenda, caja, clientes, inventario, puntos y comisiones comparten el mismo estado local. Exporta una copia JSON para conservar los datos.</p><div class="flex spaced">${button('Exportar datos','export-data','primary','download')}<a class="btn secondary" href="ESPECIFICACION_GLASSY.md" download>${icon('file')}Documento de diseño</a></div></div><div class="glass-panel">${panelHead('Integraciones reales','Un siguiente paso, claramente definido.')}<details class="accordion" open><summary>WhatsApp & Evolution API</summary><p>Necesita backend, credenciales y una sesión autorizada. El simulador no conecta ni envía mensajes reales.</p></details><details class="accordion"><summary>Pagos, PDF y tarjetas Wallet</summary><p>Los cobros son registros locales. Los comprobantes se pueden imprimir o guardar como PDF desde el navegador. La tarjeta descargable es un archivo de contacto, no un pase firmado de Apple o Google Wallet.</p></details><details class="accordion"><summary>Imágenes de producto con IA</summary><p>Se admiten imágenes locales y PNG transparentes. Un recorte automático de fondo necesitaría un servicio de procesamiento adicional.</p></details></div></div></div>`}
const viewRenderers={catalogo:catalogView,resumen:dashboardView,agenda:agendaView,reserva:()=>bookingView(false),caja:cashView,clientes:clientsView,servicios:servicesView,productos:productsView,whatsapp:whatsappView,equipo:teamView,metricas:metricsView,fidelizacion:loyaltyView,apariencia:appearanceView,portal:()=>bookingView(true),ajustes:settingsView};
